function debounce(fn, ms) {
  let timer;
  return (...args) => {
    clearTimeout(timer);              // каждое событие отодвигает вызов
    timer = setTimeout(() => fn(...args), ms);
  };
}

function throttle(fn, ms) {
  let last = 0;
  return (...args) => {
    if (Date.now() - last < ms) return; // лишние события просто выбрасываем
    last = Date.now();
    fn(...args);
  };
}

input.oninput = debounce(search, 300);   // ищем, когда перестали печатать
